using System.Collections.Generic;
using UnityEngine;

namespace Ares
{
    /// <summary>
    /// Runtime item / drop / recipe database. The JSON under Resources/Config is generated by
    /// the Excel importer, so designers only edit the spreadsheet.
    /// </summary>
    public class ItemDatabase : MonoBehaviour
    {
        public LootPickup PickupPrefab;
        public Transform PickupRoot;

        private readonly Dictionary<string, ItemDef> _items = new Dictionary<string, ItemDef>();
        private readonly Dictionary<string, Sprite> _iconCache = new Dictionary<string, Sprite>();
        private readonly List<RecipeDef> _recipes = new List<RecipeDef>();
        private DropTable _drops;
        private readonly List<LootPickup> _pickups = new List<LootPickup>(96);

        public int ItemCount { get { return _items.Count; } }
        public int PickupCount { get { return _pickups.Count; } }
        public IList<RecipeDef> Recipes { get { return _recipes; } }

        public void Init()
        {
            LoadItems();
            LoadDrops();
            LoadRecipes();
            if (PickupRoot == null)
            {
                var go = new GameObject("Pickups");
                go.transform.SetParent(transform, false);
                PickupRoot = go.transform;
            }
        }

        private void LoadItems()
        {
            _items.Clear();
            var ta = Resources.Load<TextAsset>("Config/items");
            if (ta == null)
            {
                Debug.LogError("[Ares] Resources/Config/items.json missing. Run Tools/Ares/Import Excel Config.");
                return;
            }
            var list = JsonUtility.FromJson<ItemList>(ta.text);
            if (list == null || list.items == null) return;
            for (int i = 0; i < list.items.Length; i++)
            {
                var it = list.items[i];
                if (it == null || string.IsNullOrEmpty(it.id)) continue;
                if (it.stackMax < 1) it.stackMax = 1;
                _items[it.id] = it;
            }
        }

        private void LoadDrops()
        {
            var ta = Resources.Load<TextAsset>("Config/drops");
            if (ta == null)
            {
                Debug.LogError("[Ares] Resources/Config/drops.json missing.");
                return;
            }
            _drops = JsonUtility.FromJson<DropTable>(ta.text);
        }

        private void LoadRecipes()
        {
            _recipes.Clear();
            var ta = Resources.Load<TextAsset>("Config/recipes");
            if (ta == null)
            {
                Debug.LogWarning("[Ares] Resources/Config/recipes.json missing.");
                return;
            }
            var list = JsonUtility.FromJson<RecipeList>(ta.text);
            if (list == null || list.recipes == null) return;
            for (int i = 0; i < list.recipes.Length; i++)
            {
                if (list.recipes[i] != null && !string.IsNullOrEmpty(list.recipes[i].output))
                    _recipes.Add(list.recipes[i]);
            }
        }

        public ItemDef Get(string id)
        {
            ItemDef def;
            return _items.TryGetValue(id, out def) ? def : null;
        }

        public IEnumerable<ItemDef> AllItems { get { return _items.Values; } }

        public Sprite GetIcon(string iconName)
        {
            if (string.IsNullOrEmpty(iconName)) return null;
            Sprite s;
            if (_iconCache.TryGetValue(iconName, out s)) return s;
            s = Resources.Load<Sprite>("UI/" + iconName);
            _iconCache[iconName] = s;
            return s;
        }

        /// <summary>Rolls the drop table for one kill. Called exactly once per death.</summary>
        public void RollDrops(EnemyKind kind, Vector2 position)
        {
            if (_drops == null || _drops.drops == null) return;
            string key = kind == EnemyKind.Melee ? "Melee" : kind == EnemyKind.Ranged ? "Ranged" : "Boss";

            for (int i = 0; i < _drops.drops.Length; i++)
            {
                var d = _drops.drops[i];
                if (d == null || string.IsNullOrEmpty(d.item)) continue;
                if (!string.Equals(d.enemy, key, System.StringComparison.OrdinalIgnoreCase)) continue;
                if (Random.value > d.chance) continue;

                int count = Random.Range(d.min, d.max + 1);
                if (count <= 0) continue;
                SpawnPickup(d.item, count, position + Random.insideUnitCircle * (kind == EnemyKind.Boss ? 1.4f : 0.55f));
            }
        }

        public LootPickup SpawnPickup(string itemId, int count, Vector2 position)
        {
            var def = Get(itemId);
            if (def == null)
            {
                Debug.LogWarning("[Ares] Unknown item id: " + itemId);
                return null;
            }
            if (PickupPrefab == null) return null;
            var p = Instantiate(PickupPrefab, PickupRoot);
            p.transform.position = new Vector3(position.x, position.y, 0f);
            p.Setup(def, count, this);
            _pickups.Add(p);
            return p;
        }

        public void RemovePickup(LootPickup p)
        {
            if (p == null) return;
            _pickups.Remove(p);
            Destroy(p.gameObject);
        }

        public void ClearPickups()
        {
            for (int i = _pickups.Count - 1; i >= 0; i--)
                if (_pickups[i] != null) Destroy(_pickups[i].gameObject);
            _pickups.Clear();
        }

        public LootPickup NearestPickup(Vector2 from, float radius, InventoryModel inv)
        {
            float best = radius * radius;
            LootPickup found = null;
            for (int i = 0; i < _pickups.Count; i++)
            {
                var p = _pickups[i];
                if (p == null || p.ItemId == null) continue;
                if (inv != null && !inv.CanAdd(p.ItemId, p.Count)) continue;
                float d2 = ((Vector2)p.transform.position - from).sqrMagnitude;
                if (d2 < best) { best = d2; found = p; }
            }
            return found;
        }

        public LootPickup NearestPickupAny(Vector2 from, float radius)
        {
            float best = radius * radius;
            LootPickup found = null;
            for (int i = 0; i < _pickups.Count; i++)
            {
                var p = _pickups[i];
                if (p == null) continue;
                float d2 = ((Vector2)p.transform.position - from).sqrMagnitude;
                if (d2 < best) { best = d2; found = p; }
            }
            return found;
        }

        public IReadOnlyList<LootPickup> Pickups { get { return _pickups; } }
    }
}
